export async function getBlogArticles() {

  return posts.map((raw, i) => {
    const prev = findAdjacentByLang(posts, i, raw.lang, -1);
    const next = findAdjacentByLang(posts, i, raw.lang, 1);
    return mapArticle(raw, prev, next);
  });
    
}

function findAdjacentByLang(posts, currentIndex, lang, direction) {
  let i = currentIndex + direction;
  while (i >= 0 && i < posts.length) {
    if (posts[i].lang === lang) {
      return posts[i];
    }
    i += direction;
  }
  return null;
}

function mapArticle(raw, prev, next) {
  return {
    id: String(raw.id),
       lang: raw.lang,
    slug: raw.slug,
    translationId: raw.translationId,
    title: raw.title,
    description: raw.description,
    cover: raw.cover,
    date: raw.date,
    alt: raw.alt || raw.title,
    autor: raw.autor,
    mainCategory: raw.mainCategory,
    content:{
      rendered: raw.content.rendered
    },
     counters: {
      views: raw.counters.views || 0,
      likes: raw.counters.likes || 0,
      facebookCounter: raw.counters.facebookCounter || 0
    },
    additionalsCategories: raw.additionalsCategories ?? [],
    previousPost: prev
      ? {
          id: String(prev.id),
          title: prev.title,
          cover: prev.cover,
          date: prev.date,
          slug: prev.slug,
        }
      : null,
       nextPost: next
      ? {
          id: String(next.id),
          title: next.title,
          cover: next.cover,
          date: next.date,
          slug: next.slug,
        }
      : null,
    relatedPosts: [...raw.relatedPosts ?? []],
    comments: raw.comments ?? [],
  };
}